void PowerTagBBEIdentifierCompile(
    const TokenizedIdentifier & tTokenizeIdentifier,
    IdentifierResult * ptIdentifierResult)
{
    if (!ptIdentifierResult)
        return;
    if (tTokenizeIdentifier.nStringCount != 2 && tTokenizeIdentifier.nStringCount != 3)
        return;



    SNO snoPower = SNO_NONE;
    int32 nTagIdentifierIndex = 1;
    if (tTokenizeIdentifier.nStringCount == 3) {
        snoPower = SNOFileLookupGUID(POWER_SNO, tTokenizeIdentifier.sString[1]);
        if (snoPower == SNO_NONE)
            return;
        nTagIdentifierIndex = 2;
    }















    uint32 dwTag = TagNameToTag(tTokenizeIdentifier.sString[nTagIdentifierIndex].str(), TAG_POWER_GENERAL);
    if (dwTag == (uint32)-1) {
        dwTag = TagNameToTag(tTokenizeIdentifier.sString[nTagIdentifierIndex].str(), TAG_POWER_TUNING);
        if (dwTag == (uint32)-1)
            return;
    }
    ptIdentifierResult->nIdentifier = BBE_IDENTIFIER_POWER_TAG;
    ptIdentifierResult->nParam[0] = snoPower;
    ptIdentifierResult->nParam[1] = dwTag;
    ptIdentifierResult->nParam[2] = 0;
}











float PowerTagEvaluateBBEIdentifier(
    AttribGroupID idFastAttrib,
    int32 nSkillLevel,
    SNO snoPower,
    uint32 dwPowerTag)
{
    return PowerGetFormulaValue(NULL, AutoPowerDefinitionR(snoPower), dwPowerTag, nSkillLevel, idFastAttrib, 0);
}
